mapper.select:
SELECT t.*, b.title AS block_title, b.title_en AS block_title_en
FROM coin_transaction t
LEFT JOIN block b ON b.id = t.block_id
WHERE t.user_id = #{userId}
ORDER BY t.created_at DESC, t.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT #{creatorId} AS creator_id, 
FROM block_purchase p
WHERE p.creator_id = #{creatorId}

SELECT p.*, b.title AS block_title, b.title_en AS block_title_en
FROM block_purchase p
JOIN block b ON b.id = p.block_id
WHERE p.creator_id = #{creatorId}
ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit}

mapper.update:
UPDATE creator_settlement s
SET coins = t.coins, krw = t.coins * #{krwPerCoin}
FROM (SELECT COALESCE(SUM(creator_share), 0) AS coins FROM block_purchase WHERE settlement_id = #{id}) t
WHERE s.id = #{id}

mapper.select:
SELECT id, email, nickname, coin_paid, coin_bonus FROM users WHERE is_active = true
AND (email ILIKE '%' || #{q} || '%' OR nickname ILIKE '%' || #{q} || '%')
ORDER BY (coin_paid + coin_bonus) > 0 DESC, created_at DESC, id DESC LIMIT #{limit}
